-- Workflow engine tables for the bucket schema: an instance per started workflow and its step log,
-- fenced by company like every tenant table. The outbox and inbox tables
-- the engine stages events in and dedups resumes with are created by `migrate_outbox`, as for every module
-- that stages events.
-- Generated by metaphor-schema

CREATE SCHEMA IF NOT EXISTS bucket;

CREATE TABLE IF NOT EXISTS bucket.bb_workflow_instances (
    id               uuid PRIMARY KEY,
    workflow         text NOT NULL,
    version          int  NOT NULL,
    company_id       uuid NOT NULL,
    org_unit_id      uuid,
    status           text NOT NULL CHECK (status IN ('running', 'waiting', 'completed', 'failed', 'expired', 'compensating', 'compensated', 'cancelled')),
    current_step     text,
    context          jsonb NOT NULL DEFAULT '{}'::jsonb,
    trigger_event_id uuid NOT NULL,
    correlation_id   text,
    deadline_at      timestamptz,
    wait_event       text,
    wait_key         text,
    wait_due_at      timestamptz,
    attempts         int  NOT NULL DEFAULT 0,
    last_error       text,
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_bb_workflow_instances_trigger UNIQUE (workflow, trigger_event_id)
);

CREATE INDEX IF NOT EXISTS idx_bb_workflow_instances_due
    ON bucket.bb_workflow_instances (wait_due_at)
    WHERE status IN ('waiting', 'running') AND wait_due_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_bb_workflow_instances_wait
    ON bucket.bb_workflow_instances (wait_event, wait_key)
    WHERE status = 'waiting';
CREATE INDEX IF NOT EXISTS idx_bb_workflow_instances_unfinished
    ON bucket.bb_workflow_instances (status, updated_at)
    WHERE status IN ('running', 'compensating');

CREATE TABLE IF NOT EXISTS bucket.bb_workflow_steps (
    instance_id uuid NOT NULL REFERENCES bucket.bb_workflow_instances (id) ON DELETE CASCADE,
    company_id  uuid NOT NULL,
    org_unit_id uuid,
    seq         int  NOT NULL,
    step        text NOT NULL,
    outcome     text NOT NULL,
    error       text,
    started_at  timestamptz NOT NULL DEFAULT now(),
    finished_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (instance_id, seq)
);

ALTER TABLE bucket.bb_workflow_instances ENABLE ROW LEVEL SECURITY;
ALTER TABLE bucket.bb_workflow_instances FORCE ROW LEVEL SECURITY;
ALTER TABLE bucket.bb_workflow_steps ENABLE ROW LEVEL SECURITY;
ALTER TABLE bucket.bb_workflow_steps FORCE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS bb_workflow_instances_company_isolation ON bucket.bb_workflow_instances;
CREATE POLICY bb_workflow_instances_company_isolation ON bucket.bb_workflow_instances FOR ALL
    USING      (company_id = NULLIF(current_setting('app.company_id', true), '')::uuid
                OR current_setting('app.workflow_sweep', true) = 'on')
    WITH CHECK (company_id = NULLIF(current_setting('app.company_id', true), '')::uuid);
DROP POLICY IF EXISTS bb_workflow_steps_company_isolation ON bucket.bb_workflow_steps;
CREATE POLICY bb_workflow_steps_company_isolation ON bucket.bb_workflow_steps FOR ALL
    USING      (company_id = NULLIF(current_setting('app.company_id', true), '')::uuid)
    WITH CHECK (company_id = NULLIF(current_setting('app.company_id', true), '')::uuid);
